// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/clientes", wrapper.ListarClientes)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/clientes", wrapper.GuardarCliente)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/clientes/{id}", wrapper.FichaDeCliente)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/clientes/{id}/historial", wrapper.HistorialDeCliente)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/clientes/{id}/resumen", wrapper.ResumenDeCuenta)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/clientes/{id}/credito", wrapper.CreditoDeCliente)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/clientes/{id}/movimientos", wrapper.RegistrarMovimiento)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/clientes/{id}/cuenta-web", wrapper.VincularCuentaWeb)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/admin/clientes/{id}/bloqueo", wrapper.BloquearCuenta)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/admin/clientes/{id}/plazo", wrapper.CambiarPlazo)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/clientes/{id}/cobros", wrapper.CobrarACliente)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/recibos/{id}/anular", wrapper.AnularRecibo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/recibos/{id}", wrapper.ReciboCompleto)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/recibos/{id}/pdf", wrapper.ReciboPdf)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuentas/{id}/pdf", wrapper.ResumenDeCuentaPdf)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/retenciones-sufridas", wrapper.CargarRetencionSufrida)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/cheques", wrapper.ListarCheques)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/cheques", wrapper.CargarCheque)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/cheques/terminados", wrapper.ChequesTerminados)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/cheques/cartera", wrapper.ChequesEnCartera)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/admin/cheques/{id}/estado", wrapper.CambiarEstadoDeCheque)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/vendedores", wrapper.ListarVendedores)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/vendedores", wrapper.GuardarVendedor)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/vendedores/{id}/alternar", wrapper.AlternarVendedor)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/seguimiento", wrapper.ListarGestiones)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/admin/seguimiento", wrapper.CrearGestion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/admin/seguimiento/vencidas", wrapper.GestionesVencidas)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/admin/seguimiento/{id}", wrapper.MoverGestion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/corriente", wrapper.MiCuentaCorriente)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/movimientos", wrapper.MisMovimientos)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/cuenta/credito", wrapper.MiCredito)

	return m
}

